function revisionNotes(opts){
  opts=opts||{};
  var subject=(opts.subject||'科目').trim()||'科目';
  var items=String(opts.items||'').split(/\n/).map(function(s){return s.trim();}).filter(Boolean);
  var L=[];
  L.push('# 错题本 · '+subject);
  L.push('');
  L.push('> 建议字段：日期 / 题目 / 错因 / 正确思路 / 下次复习');
  L.push('');
  if(!items.length) items=['____'];
  for(var i=0;i<items.length;i++){
    L.push('## '+(i+1)+'. '+items[i]);
    L.push('- 日期：____');
    L.push('- 错因：（概念不清 / 审题失误 / 计算错误 / 方法不对）');
    L.push('- 正确思路：');
    L.push('- 复习：☐ 1 天　☐ 3 天　☐ 7 天　☐ 15 天');
    L.push('');
  }
  return L.join('\n').replace(/\n+$/,'');
}

var EXPORTS={revisionNotes:revisionNotes};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RevisionForgePure = EXPORTS; }
